  .then(text => {
    console.log('剪贴板中的文本是：', text);
  })
  .catch(err => {
    console.error('无法读取剪贴板中的文本：', err);
  });
接下来，您需要找到要自动填充的输入框，并将剪贴板中的文本插入到该输入框中。您可以使用 JavaScript 中的 querySelector() 方法来查找页面上的元素，然后使用 .value 属性将文本插入到输入框中。例如：javascriptCopy code// 假设输入框的 ID 是 "my-input"
const input = document.querySelector('#my-input');
navigator.clipboard.readText()
  .then(text => {
    input.value = text;
  })
  .catch(err => {
    console.error('无法读取剪贴板中的文本：', err);
  });
最后，您需要确保代码在页面加载时自动运行。您可以将代码放在一个自执行函数中，或者将其放在页面的 <script> 标记中，并将该标记放在页面的 <head> 或 <body> 部分中。例如：htmlCopy code<!DOCTYPE html>
