explain promise with examples in nodejs
A promise in Node.js is an object that represents the eventual completion (or failure) of an asynchronous operation, and its resulting value. Promises are a way to handle asynchronous operations in a more organized and manageable way than using callbacks. Here's an example of using a promise to read a file from the filesystem: Copy codeconst fs = require('fs');

const readFile = fileName => {
  return new Promise((resolve, reject) => {
    fs.readFile(fileName, 'utf8', (err, data) => {
      if (err) {
        reject(err);
      } else {
        resolve(data);
      }
    });
  });
};

readFile('example.txt')
  .then(data => {
    console.log(data);
  })
  .catch(err => {
    console.error(err);
  });
In this example, readFile() returns a new promise that wraps the fs.readFile() function. The promise is resolved with the contents of the file if the read is successful, or rejected with an error if it fails. The then() and catch() methods are used to handle the resolved value or rejected reason, respectively.Another example: Copy codeconst getUser = id => {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if (id === 1) {
                resolve({id: 1, name: 'User 1'});
            } else {
                reject(new Error('User not found'));
            }
        }, 1000);
    });
};

getUser(1)
    .then(user => {
        console.log(user);
    })
    .catch(err => {
        console.error(err);
    });
In this example, getUser() returns a new promise that wraps a setTimeout, that simulates a delay in a database query. The promise is resolved with user object if the user is found, or rejected with an error if not found.
